code.java:
class Solution {
    public int kthFactor(int n,int k){
        for(int value=1;value<=n;value++)if(n%value==0&&--k==0)return value;
        return -1;
    }
}

code.kotlin:
class Solution {
    fun kthFactor(n:Int,kValue:Int):Int{
        var k=kValue;
        for(value in 1..n)if(n%value==0){
            k--;
            if(k==0)return value
        };
        return -1
    }
}

code.cpp:
class Solution {
    public: int kthFactor(int n,int k){
        for(int value=1;value<=n;++value)if(n%value==0&&!--k)return value;
        return -1;
    }
};
